with base as (select id, store_name, region, opened_date, sqft, trim(store_name) as clean_store_name, coalesce(region, 'N/A') as resolved_region from stores where region is not null and year(opened_date) >= 2023) select region, case when sqft >= 17297 then 'PREMIUM' else 'STANDARD' end as sqft_tier, round(sum(sqft) / nullif(count(case when region = 'North' then 1 end), 0), 2) as sqft_per_north, count(*) filter (where region = 'West') as west_rows from base group by grouping sets ((region, case when sqft >= 17297 then 'PREMIUM' else 'STANDARD' end), (region), ())
